function privateFillCell(curRow, curCol, text) {
    let row = table.GetRow(curRow);
    let cell = row.GetCell(curCol);
    let cellContent = cell.GetContent();
    let run = cellContent.GetElement(0).AddText(text);
    return {
        Cell: cell,
        Run: run
    };
}
privateFillCell(0, 0, "Name");
